using System;using System.IO;using System.Linq;using System.Diagnostics;using System.Threading;using System.Reflection;using System.Windows.Forms;using System.Collections.Generic;
static class WidgetInstaller {
 static void Shortcut(string path,string target,string folder){object shell=Activator.CreateInstance(Type.GetTypeFromProgID("WScript.Shell"));object link=shell.GetType().InvokeMember("CreateShortcut",BindingFlags.InvokeMethod,null,shell,new object[]{path});var t=link.GetType();t.InvokeMember("TargetPath",BindingFlags.SetProperty,null,link,new object[]{target});t.InvokeMember("WorkingDirectory",BindingFlags.SetProperty,null,link,new object[]{folder});t.InvokeMember("Arguments",BindingFlags.SetProperty,null,link,new object[]{"--follow-codex"});t.InvokeMember("IconLocation",BindingFlags.SetProperty,null,link,new object[]{Path.Combine(folder,"CodexUsageWidget.exe")+",0"});t.InvokeMember("Description",BindingFlags.SetProperty,null,link,new object[]{"Codex 한도와 작업표시줄 미니바"});t.InvokeMember("Save",BindingFlags.InvokeMethod,null,link,null);}
 public static string LaunchTarget{get{string launcher=Path.Combine(UpdateClient.InstalledFolder,"TokenWidget.exe");return File.Exists(launcher)?launcher:Application.ExecutablePath;}}
 static string StopPrevious(string target,string legacy){string previous=File.Exists(target)?target:File.Exists(legacy)?legacy:null;int statusPid=0;try{var status=SafeJson.Read<Dictionary<string,object>>(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"TeacherCodexUsageWidget","status.json"));object value;if(status.TryGetValue("pid",out value))statusPid=Convert.ToInt32(value);}catch{}try{using(var stop=EventWaitHandle.OpenExisting("Local\\TeacherCodexUsageWidget.Exit"))stop.Set();}catch{}foreach(var process in Process.GetProcessesByName("CodexUsageWidget").Concat(Process.GetProcessesByName("사용량위젯"))){try{if(process.Id==Process.GetCurrentProcess().Id)continue;string p=process.MainModule.FileName;if(!String.Equals(p,target,StringComparison.OrdinalIgnoreCase)&&!String.Equals(p,legacy,StringComparison.OrdinalIgnoreCase)&&process.Id!=statusPid)continue;previous=p;if(!process.WaitForExit(2500)){process.Kill();if(!process.WaitForExit(5000))throw new IOException("기존 위젯을 종료하지 못했습니다.");}}catch(ArgumentException){}finally{process.Dispose();}}return previous;}
 public static string Install(){string folder=UpdateClient.InstalledFolder,source=Application.StartupPath,target=Path.Combine(folder,"CodexUsageWidget.exe"),launcher=Path.Combine(folder,"TokenWidget.exe");
  foreach(var pair in new[]{new[]{"WidgetUpdater.exe",HelperInfo.Sha256},new[]{"TokenWidget.exe",LauncherInfo.Sha256}}){string f=Path.Combine(source,pair[0]);if(!File.Exists(f)||UpdatePolicy.Hash(f)!=pair[1])throw new IOException("설치 도구를 확인하지 못했습니다. 압축을 모두 푼 뒤 설치해 주세요.");}
  if(String.Equals(Path.GetFullPath(source),Path.GetFullPath(folder),StringComparison.OrdinalIgnoreCase))throw new IOException("새 배포 ZIP의 압축을 다른 폴더에 풀고 설치.cmd를 실행해 주세요.");
  string data=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"TeacherCodexUsageWidget");Directory.CreateDirectory(data);string pending=Path.Combine(data,"updates",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(pending);
  string legacy=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments),"Codex","2026-10-22","new-chat","usage-widget","CodexUsageWidget.exe");string old=StopPrevious(target,legacy);try{InstallTransaction.Recover(folder);if(old!=null&&!String.Equals(old,target,StringComparison.OrdinalIgnoreCase))SafeJson.Write(Path.Combine(folder,"previous-widget.json"),new{path=old,sha256=UpdatePolicy.Hash(old)});
  string backup=Path.Combine(data,"backups","before-"+BuildInfo.Version+"-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+"-"+Guid.NewGuid().ToString("N").Substring(0,6));WidgetBackup.Create(data,backup);
  string[] links={Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory),"Codex 사용량 위젯.lnk"),Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Programs),"내 AI 한도.lnk")};var previous=links.ToDictionary(x=>x,x=>File.Exists(x)?File.ReadAllBytes(x):null);var startup=new StartupRegistration();string command=startup.Command;
  // The recovery launcher must never be part of a transaction it might recover itself.
  if(!File.Exists(launcher))InstallTransaction.AtomicCopy(Path.Combine(source,"TokenWidget.exe"),launcher);
  string[] files=UpdatePolicy.AllowedFiles.Where(x=>x!="TokenWidget.exe"&&File.Exists(Path.Combine(source,x))).ToArray();File.WriteAllText(Path.Combine(pending,"installed-version.txt"),BuildInfo.Version);Process next=null;
  using(var tx=InstallTransaction.Begin(folder,files.Concat(new[]{"installed-version.txt"}))){try{foreach(string name in files)tx.Replace(Path.Combine(source,name),name);tx.Replace(Path.Combine(pending,"installed-version.txt"),"installed-version.txt");foreach(string link in links)Shortcut(link,launcher,folder);if(startup.Enabled)startup.SetEnabled(true,launcher,true);next=InstallTransaction.StartHealthy(target,pending,BuildInfo.Version,"--follow-codex --start-full");File.WriteAllText(Path.Combine(pending,"result.txt"),"installed "+BuildInfo.Version);tx.Commit();return target;
   }catch{InstallTransaction.Stop(next);try{tx.Rollback();}finally{foreach(string link in links){try{if(previous[link]==null){if(File.Exists(link))File.Delete(link);}else File.WriteAllBytes(link,previous[link]);}catch{}}try{startup.RestoreCommand(command);}catch{}}throw;}}
  }catch{try{InstallTransaction.Recover(folder);if(old!=null&&File.Exists(old))Process.Start(new ProcessStartInfo(old){WorkingDirectory=Path.GetDirectoryName(old),UseShellExecute=false});}catch{}throw;}
 }
 public static void Run(bool silent=false){try{Install();}catch(Exception e){try{string data=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"TeacherCodexUsageWidget");Directory.CreateDirectory(data);File.WriteAllText(Path.Combine(data,"install-error.txt"),e.ToString());}catch{}if(!silent)MessageBox.Show("설치를 완료하지 못했습니다.\n"+(e is IOException?e.Message:"기존 프로그램을 종료한 뒤 다시 시도해 주세요."),"사용량 위젯 설치",MessageBoxButtons.OK,MessageBoxIcon.Error);Environment.ExitCode=1;}}
}
